                    "CommentAdded" -> CommentAdded(id = field(data, "id", String.serializer()))
                    "CommentDeleted" -> CommentDeleted(id = field(data, "id", String.serializer()))
                    "CommentUpdated" -> CommentUpdated(id = field(data, "id", String.serializer()))
                    "CursorMoved" -> CursorMoved(identity = field(data, "identity", String.serializer()))
                    "ElementAdded" -> ElementAdded(id = field(data, "id", String.serializer()))
                    "ElementDeleted" -> ElementDeleted(id = field(data, "id", String.serializer()))
                    "ElementUpdated" -> ElementUpdated(id = field(data, "id", String.serializer()))
